import { CNCPoint } from '../data/CNCPoint';
import { CoordinateType } from '../data/Common/CoordinateType';
import { MachineStateData } from '../data/MachineStateData';
import { DROEvent, HeartbeatEvent } from '../data/SignalR/SignalREventTypes';
import { SignalRStateData } from '../data/SignalRStateData';
import { Machine } from '../machine/Machine';
import { CoordinateUtil } from './CoordinateUtil';
import { LogCategory, Logger } from './Logger';
import { ConnectionState, SignalRManager } from './SignalRManager';
import { StateManager } from './statemanager/StateManager';

/**
 * SignalRPositionUpdater - Listens for DRO and Heartbeat events and updates machine position
 * This is used in Centroid mode to keep the UI in sync with actual machine position
 */
export class SignalRPositionUpdater {
    private static _instance: SignalRPositionUpdater;
    private _isListening: boolean = false;
    private _lastConnectionState: ConnectionState = ConnectionState.Disconnected;
    private _tolerance: number = 0.0001; // Tolerance for coordinate comparison (machine units)

    private constructor() {
        // Private constructor for singleton
        // Watch for connection state changes to handle reconnection
        this._watchConnectionState();
    }

    public static get Instance(): SignalRPositionUpdater {
        if (!SignalRPositionUpdater._instance) {
            SignalRPositionUpdater._instance = new SignalRPositionUpdater();
        }
        return SignalRPositionUpdater._instance;
    }

    /**
     * Start listening for DRO and Heartbeat position updates
     */
    public startListening(): void {
        if (this._isListening) {
            return;
        }

        // Add listeners for DRO and Heartbeat events
        SignalRManager.Instance.addEventListener('DROEvent', this._handleDROEvent);
        SignalRManager.Instance.addEventListener('Heartbeat', this._handleHeartbeatEvent);
        this._isListening = true;
        Logger.Instance.log(LogCategory.DataManager, 'SignalRPositionUpdater started listening for DRO and Heartbeat events');
    }

    /**
     * Stop listening for DRO and Heartbeat position updates
     */
    public stopListening(): void {
        if (!this._isListening) {
            return;
        }

        SignalRManager.Instance.removeEventListener('DROEvent', this._handleDROEvent);
        SignalRManager.Instance.removeEventListener('Heartbeat', this._handleHeartbeatEvent);
        this._isListening = false;
        Logger.Instance.log(LogCategory.DataManager, 'SignalRPositionUpdater stopped listening for DRO and Heartbeat events');
    }

    /**
     * Handle DRO event from SignalR
     */
    private _handleDROEvent = (event: DROEvent): void => {
        try {
            const data = event.data;

            // Create CNCPoint from DRO data
            // DRO data comes in MachineHome coordinates from Centroid
            // (relative to machine home corner, not machine zero)
            const machineHomePosition = new CNCPoint(
                data.axis1, // X
                data.axis2, // Y
                data.axis3, // Z
                CoordinateType.MachineHome
            );

            // Convert to MachineZero coordinates (the system currentMachinePoint uses)
            const newPosition = CoordinateUtil.toMachineZero(machineHomePosition);

            // Update position if it's different
            this._updatePositionIfDifferent(newPosition);
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Error handling DRO event:', error);
        }
    };

    /**
     * Handle Heartbeat event from SignalR
     */
    private _handleHeartbeatEvent = (event: HeartbeatEvent): void => {
        try {
            const data = event.data;

            // Update connection state in MachineStateData
            MachineStateData.Instance.isConnected = data.isConnected;

            // Only process position if connected and position data is available
            if (!data.isConnected || !data.position) {
                return;
            }

            // Create CNCPoint from heartbeat position data
            // Heartbeat position comes in MachineHome coordinates
            const machineHomePosition = new CNCPoint(
                data.position.x,
                data.position.y,
                data.position.z,
                CoordinateType.MachineHome
            );

            // Convert to MachineZero coordinates (the system currentMachinePoint uses)
            const newPosition = CoordinateUtil.toMachineZero(machineHomePosition);

            // Update position if it's different
            this._updatePositionIfDifferent(newPosition);
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Error handling Heartbeat event:', error);
        }
    };

    /**
     * Update machine position if it differs from current position
     */
    private _updatePositionIfDifferent(newPosition: CNCPoint): void {
        const currentPosition = MachineStateData.Instance.currentMachinePoint;

        // Compare coordinates with tolerance
        const xDifferent = Math.abs(currentPosition.x - newPosition.x) > this._tolerance;
        const yDifferent = Math.abs(currentPosition.y - newPosition.y) > this._tolerance;
        const zDifferent = Math.abs(currentPosition.z - newPosition.z) > this._tolerance;

        // Only update if at least one coordinate has changed significantly
        if (xDifferent || yDifferent || zDifferent) {
            MachineStateData.Instance.currentMachinePoint = newPosition;
            StateManager.propertyChanged(MachineStateData.Instance, 'currentMachinePoint');
        }

        // Position updates happen constantly - no logging needed
    }

    /**
     * Watch for connection state changes to handle reconnection
     */
    private _watchConnectionState(): void {
        // Check connection state periodically
        setInterval(() => {
            const currentState = SignalRStateData.Instance.connectionState;

            // Update MachineStateData connection state based on SignalR state
            if (currentState === ConnectionState.Disconnected || currentState === ConnectionState.Reconnecting) {
                MachineStateData.Instance.isConnected = false;
            }

            // Detect when we transition from Reconnecting/Disconnected to Connected
            if (currentState === ConnectionState.Connected &&
                (this._lastConnectionState === ConnectionState.Reconnecting ||
                    this._lastConnectionState === ConnectionState.Disconnected)) {

                this._handleReconnection();
            }

            this._lastConnectionState = currentState;
        }, 1000); // Check every second
    }

    /**
     * Handle reconnection - re-establish fixture/work zero with the machine
     */
    private _handleReconnection = async (): Promise<void> => {
        try {
            const machine = Machine.getInstance();

            // Re-establish the fixture point (work zero)
            await machine.movement.SetCurrentFixturePoint();
            
            Logger.Instance.log(LogCategory.Network, 'Re-established fixture point after reconnection');
        } catch (error) {
            Logger.Instance.logError(LogCategory.Network, 'Failed to re-establish fixture point after reconnection:', error);
        }
    };

    /**
     * Check if currently listening
     */
    public get isListening(): boolean {
        return this._isListening;
    }
}
